import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { NavBar } from './components/NavBar';
import { LoginScreen } from './components/LoginScreen';
import { ItemLookupScreen } from './components/ItemLookupScreen';
import { ReceivingScreen } from './components/ReceivingScreen';
import { PurchaseOrderListScreen } from './components/PurchaseOrderListScreen';
import { PurchaseOrderDetailScreen } from './components/PurchaseOrderDetailScreen';
import { ReportsListScreen } from './components/ReportsListScreen';
import { AuthProvider, useAuth } from './components/AuthContext';

function App() {
  const { user, loading } = useAuth();

  if (loading) return <div>Loading...</div>;

  return (
    <Router>
      <div className="App">
        <NavBar />
        <main className="main-content">
          <Routes>
            <Route path="/" element={user ? <ItemLookupScreen /> : <LoginScreen />} />
            <Route path="/login" element={<LoginScreen />} />
            <Route path="/item-lookup" element={user ? <ItemLookupScreen /> : <LoginScreen />} />
            <Route path="/receiving" element={user ? <ReceivingScreen /> : <LoginScreen />} />
            <Route path="/purchase-orders" element={user ? <PurchaseOrderListScreen /> : <LoginScreen />} />
            <Route path="/purchase-orders/:id" element={user ? <PurchaseOrderDetailScreen /> : <LoginScreen />} />
            <Route path="/reports" element={user ? <ReportsListScreen /> : <LoginScreen />} />
          </Routes>
        </main>
      </div>
    </Router>
  );
}

export default App;
